export type ServiceKind = "fuel" | "grocery" | "asianGrocery" | "asianFood" | "dcFast";

export interface ServicePoint {
  kind: ServiceKind;
  name: string;
  lat: number; // 5 decimals
  lon: number;
  /** 品牌（加油站、超市），OSM 的 brand 标签 */
  brand?: string;
  /** 快充：是不是 Tesla 超充 */
  tesla?: boolean;
  /** 快充：直流快充桩数 */
  ports?: number;
}

export const servicesUpdated = "2026-09-26";

